// A tally counting evaluations, its state fed back through the graph,
// carried into the new tally by tally.upgrade@1 when the layout changes.
use "kernels/";

node seed: tally.zero@1 { domain = 1; }
node count: tally.step@1 { previous <~ count.result from seed.result migrate tally.upgrade@1; }

output result <- count.result;

